import bpy, numpy as np

def load(p):
    im = bpy.data.images.load(p)
    a = np.array(im.pixels[:], dtype=np.float32).reshape(im.size[1], im.size[0], 4)[::-1,:,:3].copy()
    bpy.data.images.remove(im)
    return a

refs = np.load('/app/output/refs.npy')
my1 = load('/app/output/my_v1.png'); my4 = load('/app/output/my_v4.png')

def dilate(m, it=4):
    for _ in range(it):
        m = m | np.roll(m,1,0) | np.roll(m,-1,0) | np.roll(m,1,1) | np.roll(m,-1,1)
    return m

def marble_mask(img, x0,x1,y0,y1):
    sat = img.max(axis=2)-img.min(axis=2)
    m = (sat<0.10)&(img.min(axis=2)>0.40)&(img.max(axis=2)<0.74)
    mm = np.zeros_like(m); mm[y0:y1, x0:x1] = True
    return dilate(m & mm)

for tag, img, box in [('ref1',refs[1],(150,460,220,420)), ('my1',my1,(150,460,220,420)),
                      ('ref4',refs[4],(420,720,330,620)), ('my4',my4,(420,720,330,620))]:
    m = marble_mask(img, *box)
    ys,xs = np.nonzero(m)
    print('%s marble n=%d x[%d,%d] y[%d,%d]'%(tag,len(xs),xs.min(),xs.max(),ys.min(),ys.max()))
    for cx in range(xs.min(), xs.max()+1, 25):
        col = np.nonzero(m[:,cx])[0]
        if len(col): print('   col %d: py[%d,%d]'%(cx,col.min(),col.max()))

