 'flamp': ['fl_base','fl_stem','fl_shade'],
}

def group_bbox(g):
    pts = []
    for n in groups[g]:
        ob = bpy.data.objects[n]
        for c in ob.bound_box:
            pts.append(ob.matrix_world @ mathutils.Vector(c))
    P = np.array([[p.x,p.y,p.z] for p in pts])
    return P.min(axis=0), P.max(axis=0)

gb = {}
for g in groups:
    lo, hi = group_bbox(g)
    gb[g] = (lo, hi)
    print(g, 'x[%.2f,%.2f] y[%.2f,%.2f] z[%.2f,%.2f]' % (lo[0],hi[0],lo[1],hi[1],lo[2],hi[2]))

# corners of the bbox (all 8) for projection
def corners(g):
    lo, hi = gb[g]
    cs = []
    for sx in (0,1):
        for sy in (0,1):
            for sz in (0,1):
                cs.append((lo[0] if sx else hi[0], lo[1] if sy else hi[1], lo[2] if sz else hi[2]))
    return cs

def proj_bbox(g, cam, dx=0.0, dy=0.0):
    cs = corners(g)
    pxs, pys = [], []
    for (x,y,z) in cs:
        cd = world_to_camera_view(scene, cam, mathutils.Vector((x+dx, y+dy, z)))
        if cd.z <= 0: return None
        pxs.append(cd.x*768); pys.append((1-cd.y)*768)
    return (min(pxs), max(pxs), min(pys), max(pys))

